core=dict(status='usable',rationale='The representative normal proposal and authority paths, including membership, storage, recovery and library completion boundaries, have been read through their actual producers and consumers. This is a scoped mechanism map, not an execution result or correctness finding.',formation=path('RawNode.Propose creates MsgProp; Node.run serializes the equivalent state-machine work, while RawNode callers must serialize their own calls. A follower forwards only to a known leader; a candidate drops it. The leader checks membership, transfer and quota, assigns current term/index, appends unstable entries and broadcasts MsgApp anchored by predecessor index/term. The follower checks term and predecessor, rejects conflicts or appends a suffix without overwriting committed history, and queues MsgAppResp. send defers append/election support, including self support, through the Ready storage boundary. After legal caller persistence and delivery, leader response handling records sender Match. The active voter quorum aggregates these values (both majorities in joint configuration); maybeCommit additionally requires a current-term entry beyond committed. Commit is recorded in raftLog and HardState and propagated by append or heartbeat, whose commit is capped by recipient Match. Ready exposes committed application work; async application is additionally bounded by local stabilization. Actual client reply is outside this library and Propose success does not guarantee commitment.', ['B_propose','B_append_receive','B_defer_support','B_match','B_commit','B_apply'],['S_api','S_node','S_proposal','S_replicate','S_receive','S_send','S_ready','S_responses','S_tracker_commit','S_joint','S_majority','S_log_term','S_log_apply','S_usage'],['F_match']),context=path('Startup reads log boundaries, HardState and ConfState, reconstructs configuration and becomes follower. Bootstrap is a separate empty-storage initialization that creates committed configuration entries for the caller to persist/apply. Campaign requires a voter with no pending snapshot and no unapplied committed configuration change. Pre-vote can precede real candidacy; real candidacy increments term and records self-vote, but counting the self response waits on storage processing. Vote grant checks vote availability and candidate last term/index. Candidate tally counts configured voters and both joint majorities. Winning enters leader role and appends an empty current-term entry. Step processes message terms before role handlers: ordinary higher terms step down, lower terms are discarded with explicit pre-vote, stale leader and storage-completion exceptions. CheckQuorum can remove authority at the same term; transfer pauses proposals, catches up an eligible peer and issues TimeoutNow with timeout/abort paths. Configuration activation may remove/demote leadership depending on configured behavior.', ['B_authority','B_recover','B_membership','B_defer_support'],['S_init','S_bootstrap','S_transition','S_election','S_roles','S_responses','S_tracker_votes','S_joint','S_majority','S_membership','S_options']),connection=path('Authority reset keeps log/committed history but clears vote tally, remote progress, transfer and readOnly acknowledgment state; it initializes self Match from the retained last index, so Match is not intrinsically a fresh durable acknowledgment. Old-term network append/election replies cannot update current-role support. Local append stabilization requires both sending-term validity and entry index/log-term match. Snapshot completion and committed application are allowed to survive term change because their objects are committed state; application responses deliberately carry term zero. The committed prefix constrains future append replacement and election log freshness; committing an entry in the new leader term advances eligible prior entries as part of the prefix. Membership activates during application, retains surviving progress, initializes new members to zero and changes the quorum consumer. Pending ReadIndex messages waiting for first current-term commit survive reset, whereas readOnly acknowledgment maps are replaced; release re-enters the read protocol after current-term commit. Already-produced ReadStates also survive until Ready consumption. Safe reads correlate request contexts with heartbeat acknowledgments and configured voter quorum; singleton and lease-based paths differ. Their application-visible linearizability remains untested.', ['B_authority','B_match','B_commit','B_membership','B_defer_support','B_apply'],['S_transition','S_election','S_ready','S_unstable','S_log_append','S_log_term','S_change_members','S_membership','S_proposal','S_responses','S_read','S_read_release','S_read_queue'],['F_match']),core_gaps=[],open_details=['ReadIndex request context uniqueness, repeated context behavior and configuration transition interactions need focused mapping before any Candidate depends on them.','MemoryStorage compaction/reconstruction and real durable backend behavior have not been explored beyond interface and startup paths.','Detailed inflight window/rejection recovery schedules remain unexpanded.','Ready field comments and doc.go differ in how they describe same-batch persistence/send concurrency; a concrete check must state its API mode and use a legal conservative ordering.'])
surfaces=[dict(entry_point='newStorageAppendRespMsg -> raft.Step -> unstable.stableTo',disposition='mapped',behavior_ids=['B_defer_support'],reason='Sending-term and log-entry identity protect different stages; next discriminator can execute delayed completion across an actual term transition.',source_ids=['S_ready','S_election','S_unstable'],high_consequence=True),dict(entry_point='ReadIndex / pendingReadIndexMessages / readOnly.advance',disposition='deferred',reason='Source reveals separate pre-commit queue, acknowledgment map and Ready result queue; no single request lifecycle or candidate is yet mapped.',source_ids=['S_proposal','S_read','S_read_release','S_read_queue','S_roles'],high_consequence=True),dict(entry_point='ApplyConfChange -> switchToConfig -> maybeCommit',disposition='mapped',behavior_ids=['B_membership','B_commit'],reason='Quorum change can consume retained matches without a new acknowledgment. Legality depends on committed configuration application, which a future check must construct.',source_ids=['S_membership','S_change_members'],high_consequence=True),dict(entry_point='Caller storage worker and application/client response',disposition='externalized',reason='This library exposes contracts, storage requests and application work. The Node wrapper is in-repository and mapped; no durable application backend has been attributed.',source_ids=['S_config','S_usage','S_storage','S_node'],high_consequence=True)]
audit=dict(version=1,target_profile=dict(system_boundary='Captured go.etcd.io/raft library: RawNode state machine, Node serialized wrapper, log, tracker/quorum, membership and Storage abstraction. Transport, durable writes and application/client completion are caller responsibilities.',protocol_contexts=['One raft instance/group, node ID, term, role, log entry term/index and active incoming/outgoing voter configuration.'],external_interfaces=['RawNode/Node proposal, message, tick, Ready, Advance and configuration application interfaces; Storage.'],ownership=['Node.run owns serialized processing; RawNode is thread-unsafe and requires caller serialization.'],selection_injection=['Config supplies storage, IDs, timer parameters and behavioral options.'],variants=['Sync Ready/Advance and AsyncStorageWrites','Single and joint majority voter configuration with learners','PreVote, CheckQuorum, read safe/lease, forwarding and removal options'],source_ids=['S_api','S_node','S_config','S_options','S_storage','S_joint'],unknowns=['No deployment-specific backend, fault schedule or application completion has been observed.']),activities=activities,behaviors=B,facts=[fact],surfaces=surfaces,core_overview=core)
